?><div class="admin-panel editor-form"><div class="admin-editor-title"><h3><?=$project?'ویرایش پروژه و گالری':'افزودن پروژه'?></h3><?php if($project):?><a href="<?=e(project_url($project))?>" target="_blank" rel="noopener">مشاهده صفحه اثر ↗</a><?php endif;?></div><form method="post" enctype="multipart/form-data"><?php hidden('project');?><input type="hidden" name="id" value="<?=$project?$edit:''?>"><div class="form-row"><label>عنوان پروژه<input name="title" value="<?=e($project['title']??'')?>" maxlength="120" required></label><label>دسته‌بندی<select name="category"><?php foreach(['branding'=>'هویت بصری و برندینگ','film'=>'تولید محتوا و تصویر','digital'=>'وب و تجربه دیجیتال','campaign'=>'کمپین و رویداد'] as $k=>$v):?><option value="<?=$k?>" <?=($project['category']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div><label>برچسب نمایشی<input name="label" value="<?=e($project['label']??'')?>" required maxlength="120" placeholder="مثلاً طراحی هویت بصری"></label><div class="form-row"><label>کارفرما (اختیاری)<input name="client" maxlength="120" value="<?=e($project['client']??'')?>"></label><label>سال اجرا (اختیاری)<input name="year" maxlength="12" value="<?=e($project['year']??'')?>"></label></div><label>خدمات ارائه‌شده (اختیاری)<input name="role" value="<?=e($project['role']??'')?>" maxlength="200" placeholder="مثلاً استراتژی برند، طراحی لوگو و بسته‌بندی"></label><label>توضیحات کامل پروژه<textarea name="description" rows="7" maxlength="10000" required><?=e($project['description']??'')?></textarea></label><p class="admin-hint">متن به‌صورت امن و بدون کد HTML در صفحه اختصاصی همین پروژه نمایش داده می‌شود. پاراگراف‌ها را با Enter جدا کنید.</p><h3>کاور اثر</h3><?php if(!empty($project['image'])&&media_path($project['image'])):?><img class="admin-cover-preview" src="<?=e(media_path($project['image']))?>" alt="کاور فعلی"><label class="brand-check"><input type="checkbox" name="remove_cover" value="1"> حذف کاور فعلی و نمایش طرح پیش‌فرض</label><?php endif;?><label>تصویر کاور (JPG، PNG یا WebP؛ حداکثر ۵ مگابایت)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><p class="admin-hint">اگر تصویری انتخاب نکنید، در ویرایش کاور فعلی حفظ می‌شود؛ برای پروژه جدید یک طرح مفهومی متناسب با دسته نمایش داده می‌شود.</p><h3>گالری اختصاصی پروژه</h3><?php if(!empty($project['gallery'])):?><div class="admin-gallery-grid"><?php foreach($project['gallery'] as $i=>$media):?><div class="admin-gallery-item"><img src="<?=e(media_path($media['image']))?>" alt="تصویر <?=$i+1?>"><label>توضیح تصویر<input name="gallery_form[<?=$i?>][caption]" value="<?=e($media['caption']??'')?>" maxlength="200"></label><label>ترتیب نمایش<input type="number" name="gallery_form[<?=$i?>][order]" min="0" max="999" value="<?=$i?>"></label><label class="brand-check"><input type="checkbox" name="gallery_form[<?=$i?>][remove]" value="1"> حذف از گالری</label></div><?php endforeach;?></div><?php else:?><p class="admin-hint">هنوز تصویری برای گالری این اثر بارگذاری نشده است.</p><?php endif;?><label>افزودن تصاویر جدید به گالری<input type="file" name="gallery[]" accept="image/jpeg,image/png,image/webp" multiple></label><p class="admin-hint">در هر ذخیره حداکثر ۸ تصویر، هر تصویر تا ۵ مگابایت. هر پروژه حداکثر ۲۴ تصویر. پس از ذخیره، توضیح و ترتیب هر تصویر در همین بخش قابل ویرایش است. تصاویر جدید به انتهای گالری اضافه می‌شوند.</p><h3>ویدیوی پروژه (اختیاری)</h3><label>لینک مستقیم HTTPS ویدیو<input name="video_url" type="url" dir="ltr" value="<?=e($project['video_url']??'')?>" maxlength="2000" placeholder="https://example.com/video.mp4"></label><p class="admin-hint">لینک مستقیم MP4 یا WebM از هاست یا فضای رسانه خودتان؛ لینک صفحه آپارات یا یوتیوب نیست. ویدیو فقط پس از انتخاب بازدیدکننده پخش می‌شود.</p><div class="admin-actions"><button class="button primary">ذخیره پروژه و گالری</button><?php if($project):?><a class="button secondary" href="?tab=projects">انصراف از ویرایش</a><?php endif;?></div></form></div><div class="admin-panel"><h3>آثار منتشرشده</h3><?php if(empty($site['projects'])):?><p class="admin-hint">هنوز اثری منتشر نشده است.</p><?php endif;?><?php foreach($site['projects'] as $i=>$p):?><div class="admin-project-row"><div><b><?=e($p['title'])?></b><small><?=e($p['label'])?> · <?=count($p['gallery']??[])?> تصویر گالری</small></div><div class="row-actions"><a href="<?=e(project_url($p))?>" target="_blank" rel="noopener">مشاهده</a><a href="?tab=projects&edit=<?=$i?>">ویرایش</a><form method="post" data-confirm="این پروژه و اطلاعات گالری آن حذف شود؟"><?php hidden('delete_project');?><input type="hidden" name="id" value="<?=$i?>"><button class="danger-text">حذف</button></form></div></div><?php endforeach;?></div>
